type flags struct {
	raw      bool
	slurp    bool
	yaml     bool
	toml     bool
	strict   bool
	noInline bool
	gol      bool
	args     []string
}

func parseArgs(argv []string) (*flags, bool, string, string) {
	f := &flags{}
	i := 0
	for i < len(argv) {
		a := argv[i]
		switch a {
		case "-h", "--help":
			return nil, true, "help", ""
		case "-v", "--version":
			return nil, true, "version", ""
		case "--themes":
			return nil, true, "themes", ""
		case "--comp":
			i++
			if i >= len(argv) {
				return nil, true, "comp", ""
			}
			return nil, true, "comp", argv[i]
		case "-r", "--raw":
			f.raw = true
		case "-s", "--slurp":
			f.slurp = true
		case "-rs", "-sr":
			f.raw = true
			f.slurp = true
		case "--yaml":
			f.yaml = true
		case "--toml":
			f.toml = true
		case "--strict":
			f.strict = true
		case "--no-inline":
			f.noInline = true
		case "--game-of-life":
			f.gol = true
		default:
			f.args = append(f.args, a)
		}
		i++
	}
	return f, false, "", ""
}

// ---------- JSON parsing ----------

type Kind int

const (
	KNull Kind = iota
	KBool
	KNumber
	KString
	KArray
	KObject
)

type Value struct {
	K    Kind
	B    bool
	N    string // number as raw text
	S    string
	Arr  []*Value
	Keys []string
	Map  map[string]*Value // order via Keys
}

type Parser struct {
	src    []byte
	pos    int
	strict bool
}

type parseErr struct {
	msg string
	pos int
}

func (e *parseErr) Error() string { return e.msg }

func (p *Parser) fail(msg string, pos int) error {
	return &parseErr{msg: msg, pos: pos}
}

func (p *Parser) skipWS() error {
	for p.pos < len(p.src) {
		c := p.src[p.pos]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			p.pos++
			continue
		}
		if c == '/' && p.pos+1 < len(p.src) {
			nc := p.src[p.pos+1]
			if nc == '/' {
				if p.strict {
					return p.fail(fmt.Sprintf("Comments are not allowed in strict mode"), p.pos)
				}
				// skip until end of line
				p.pos += 2
				for p.pos < len(p.src) && p.src[p.pos] != '\n' {
					p.pos++
				}
				continue
			} else if nc == '*' {
				if p.strict {
					return p.fail("Comments are not allowed in strict mode", p.pos)
				}
				p.pos += 2
				for p.pos+1 < len(p.src) {
					if p.src[p.pos] == '*' && p.src[p.pos+1] == '/' {
						p.pos += 2
						break
					}
					p.pos++
				}
				continue
			}
		}
		break
	}
	return nil
}

func (p *Parser) parseValue() (*Value, error) {
	if err := p.skipWS(); err != nil {
		return nil, err
	}
	if p.pos >= len(p.src) {
		return nil, p.fail(fmt.Sprintf("Unexpected character '%s'", renderChar(0)), p.pos)
	}
	c := p.src[p.pos]
	switch {
	case c == '{':
		return p.parseObject()
	case c == '[':
		return p.parseArray()
	case c == '"':
		s, err := p.parseString()
		if err != nil {
			return nil, err
		}
		return &Value{K: KString, S: s}, nil
	case c == 't' || c == 'f':
		return p.parseBool()
	case c == 'n':
		return p.parseNull()
	case c == '-' || (c >= '0' && c <= '9'):
		return p.parseNumber()
	case !p.strict && (c == 'N' || c == 'I'):
		// NaN or Infinity
		return p.parseSpecialNumber()
	}
	return nil, p.fail(fmt.Sprintf("Unexpected character '%s'", renderChar(c)), p.pos)
}

func (p *Parser) parseObject() (*Value, error) {
	start := p.pos
	_ = start
	p.pos++ // {
	v := &Value{K: KObject, Map: map[string]*Value{}}
	if err := p.skipWS(); err != nil {
		return nil, err
	}
	if p.pos < len(p.src) && p.src[p.pos] == '}' {
		p.pos++
		return v, nil
	}
	for {
		if err := p.skipWS(); err != nil {
			return nil, err
		}
		if p.pos >= len(p.src) {
			return nil, p.fail(fmt.Sprintf("Expected object key to be a string, got '%s'", renderChar(0)), p.pos)
		}
		c := p.src[p.pos]
		if c != '"' {
			return nil, p.fail(fmt.Sprintf("Expected object key to be a string, got '%s'", renderChar(c)), p.pos)
		}
		key, err := p.parseString()
		if err != nil {
			return nil, err
		}
		if err := p.skipWS(); err != nil {
			return nil, err
		}
		if p.pos >= len(p.src) || p.src[p.pos] != ':' {
			ch := byte(0)
			if p.pos < len(p.src) {
				ch = p.src[p.pos]
			}
			return nil, p.fail(fmt.Sprintf("Expected ':' after key, got '%s'", renderChar(ch)), p.pos)
		}
		p.pos++
		val, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		if _, exists := v.Map[key]; !exists {
			v.Keys = append(v.Keys, key)
		}
		v.Map[key] = val
		if err := p.skipWS(); err != nil {
			return nil, err
		}
		if p.pos >= len(p.src) {
			return nil, p.fail("Unexpected end of input in object", p.pos)
		}
		if p.src[p.pos] == ',' {
			p.pos++
			if err := p.skipWS(); err != nil {
				return nil, err
			}
			if p.pos < len(p.src) && p.src[p.pos] == '}' {
				if p.strict {
					return nil, p.fail("Trailing comma is not allowed in strict mode", p.pos-1)
				}
				p.pos++
				return v, nil
			}
			continue
		}
		if p.src[p.pos] == '}' {
			p.pos++
			return v, nil
		}
		return nil, p.fail(fmt.Sprintf("Unexpected character '%s' in object", renderChar(p.src[p.pos])), p.pos)
	}
}

func (p *Parser) parseArray() (*Value, error) {
	p.pos++ // [
	v := &Value{K: KArray}
	if err := p.skipWS(); err != nil {
		return nil, err
	}
	if p.pos < len(p.src) && p.src[p.pos] == ']' {
		p.pos++
		return v, nil
	}
	for {
		elem, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		v.Arr = append(v.Arr, elem)
		if err := p.skipWS(); err != nil {
			return nil, err
		}
		if p.pos >= len(p.src) {
			return nil, p.fail("Unexpected end of input in array", p.pos)
		}
		if p.src[p.pos] == ',' {
			p.pos++
			if err := p.skipWS(); err != nil {
				return nil, err
			}
			if p.pos < len(p.src) && p.src[p.pos] == ']' {
				if p.strict {
					return nil, p.fail("Trailing comma is not allowed in strict mode", p.pos-1)
				}
				p.pos++
				return v, nil
			}
			continue
		}
		if p.src[p.pos] == ']' {
			p.pos++
			return v, nil
		}
		return nil, p.fail(fmt.Sprintf("Unexpected character '%s' in array", renderChar(p.src[p.pos])), p.pos)
	}
}

func (p *Parser) parseString() (string, error) {
	p.pos++ // "
	var sb strings.Builder
	for p.pos < len(p.src) {
		c := p.src[p.pos]
		if c == '"' {
			p.pos++
			return sb.String(), nil
		}
		if c == '\\' {
			p.pos++
			if p.pos >= len(p.src) {
				return "", p.fail("Unexpected end of string", p.pos)
			}
			esc := p.src[p.pos]
			switch esc {
			case '"':
				sb.WriteByte('"')
			case '\\':
				sb.WriteByte('\\')
			case '/':
				sb.WriteByte('/')
			case 'b':
				sb.WriteByte('\b')
			case 'f':
				sb.WriteByte('\f')
			case 'n':
				sb.WriteByte('\n')
			case 'r':
				sb.WriteByte('\r')
			case 't':
				sb.WriteByte('\t')
			case 'u':
				if p.pos+4 >= len(p.src) {
					return "", p.fail("Invalid unicode escape", p.pos)
				}
				hex := string(p.src[p.pos+1 : p.pos+5])
				n, err := strconv.ParseUint(hex, 16, 32)
				if err != nil {
					return "", p.fail("Invalid unicode escape", p.pos)
				}
				sb.WriteRune(rune(n))
				p.pos += 4
			default:
				return "", p.fail(fmt.Sprintf("Invalid escape character '%s'", renderChar(esc)), p.pos)
			}
			p.pos++
			continue
		}
		sb.WriteByte(c)
		p.pos++
	}
	return "", p.fail("Unexpected end of input in string", p.pos)
}

func (p *Parser) parseBool() (*Value, error) {
	if p.pos+4 <= len(p.src) && string(p.src[p.pos:p.pos+4]) == "true" {
		p.pos += 4
		return &Value{K: KBool, B: true}, nil
	}
	if p.pos+5 <= len(p.src) && string(p.src[p.pos:p.pos+5]) == "false" {
		p.pos += 5
		return &Value{K: KBool, B: false}, nil
	}
	return nil, p.fail(fmt.Sprintf("Unexpected character '%s'", renderChar(p.src[p.pos])), p.pos)
}

func (p *Parser) parseNull() (*Value, error) {
	if p.pos+4 <= len(p.src) && string(p.src[p.pos:p.pos+4]) == "null" {
		p.pos += 4
		return &Value{K: KNull}, nil
	}
	return nil, p.fail(fmt.Sprintf("Unexpected character '%s'", renderChar(p.src[p.pos])), p.pos)
}

func (p *Parser) parseSpecialNumber() (*Value, error) {
	if p.pos+3 <= len(p.src) && string(p.src[p.pos:p.pos+3]) == "NaN" {
		p.pos += 3
		return &Value{K: KNumber, N: "NaN"}, nil
	}
	if p.pos+8 <= len(p.src) && string(p.src[p.pos:p.pos+8]) == "Infinity" {
		p.pos += 8
		return &Value{K: KNumber, N: "Infinity"}, nil
	}
	return nil, p.fail(fmt.Sprintf("Unexpected character '%s'", renderChar(p.src[p.pos])), p.pos)
}

func (p *Parser) parseNumber() (*Value, error) {
	start := p.pos
	if p.src[p.pos] == '-' {
		p.pos++
	}
	if p.pos < len(p.src) && p.src[p.pos] == '0' {
		p.pos++
	} else if p.pos < len(p.src) && p.src[p.pos] >= '1' && p.src[p.pos] <= '9' {
		for p.pos < len(p.src) && p.src[p.pos] >= '0' && p.src[p.pos] <= '9' {
			p.pos++
		}
	} else {
		return nil, p.fail(fmt.Sprintf("Invalid character '%s' in number", renderChar(p.src[p.pos])), p.pos)
	}
	if p.pos < len(p.src) && p.src[p.pos] == '.' {
		p.pos++
		numAfterDot := 0
		for p.pos < len(p.src) && p.src[p.pos] >= '0' && p.src[p.pos] <= '9' {
			p.pos++
			numAfterDot++
		}
		if numAfterDot == 0 {
			ch := byte(0)
			if p.pos < len(p.src) {
				ch = p.src[p.pos]
			}
			return nil, p.fail(fmt.Sprintf("Invalid character '%s' in number", renderChar(ch)), p.pos)
		}
	}
	if p.pos < len(p.src) && (p.src[p.pos] == 'e' || p.src[p.pos] == 'E') {
		p.pos++
		if p.pos < len(p.src) && (p.src[p.pos] == '+' || p.src[p.pos] == '-') {
			p.pos++
		}
		numExp := 0
		for p.pos < len(p.src) && p.src[p.pos] >= '0' && p.src[p.pos] <= '9' {
			p.pos++
			numExp++
		}
		if numExp == 0 {
			ch := byte(0)
			if p.pos < len(p.src) {
				ch = p.src[p.pos]
			}
			return nil, p.fail(fmt.Sprintf("Invalid character '%s' in number", renderChar(ch)), p.pos)
		}
	}
	return &Value{K: KNumber, N: string(p.src[start:p.pos])}, nil
}

func renderChar(c byte) string {
	if c == 0 {
		return "\\x00"
	}
	if c < 32 {
		return fmt.Sprintf("\\x%02x", c)
	}
	return string(c)
}

// ---------- error rendering ----------

func renderParseError(src []byte, perr *parseErr) string {
	// Find line/col
	line := 1
	col := 0
	lineStart := 0
	for i := 0; i < perr.pos && i < len(src); i++ {
		if src[i] == '\n' {
			line++
			col = 0
			lineStart = i + 1
		} else {
			col++
		}
	}
	// Extract current line from src
	lineEnd := lineStart
	for lineEnd < len(src) && src[lineEnd] != '\n' {
		lineEnd++
	}
	lineText := string(src[lineStart:lineEnd])
	var sb strings.Builder
	sb.WriteString(perr.msg)
	sb.WriteString(fmt.Sprintf(" on line %d.\n\n", line))
	sb.WriteString("  ")
	sb.WriteString(lineText)
	sb.WriteString("\n  ")
	for i := 0; i < col; i++ {
		sb.WriteByte('.')
	}
	sb.WriteString("^\n\n")
	return sb.String()
}

// ---------- JSON formatting ----------

type printer struct {
	buf      strings.Builder
	noInline bool
}

func escapeJSONString(s string) string {
	var sb strings.Builder
	sb.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			sb.WriteString("\\\"")
		case '\\':
			sb.WriteString("\\\\")
		case '\n':
			sb.WriteString("\\n")
		case '\r':
			sb.WriteString("\\r")
		case '\t':
			sb.WriteString("\\t")
		case '\b':
			sb.WriteString("\\b")
		case '\f':
			sb.WriteString("\\f")
		default:
			if r < 0x20 {
				sb.WriteString(fmt.Sprintf("\\u%04x", r))
			} else {
				sb.WriteRune(r)
			}
		}
	}
	sb.WriteByte('"')
	return sb.String()
}

// Render value inline (single-line) unconditionally. Used to get size estimate
// and for actual inline rendering.
func (p *printer) renderInline(v *Value) string {
	switch v.K {
	case KNull:
		return "null"
	case KBool:
		if v.B {
			return "true"
		}
		return "false"
	case KNumber:
		return v.N
	case KString:
		return escapeJSONString(v.S)
	case KArray:
		if len(v.Arr) == 0 {
			return "[]"
		}
		parts := make([]string, len(v.Arr))
		for i, c := range v.Arr {
			parts[i] = p.renderInline(c)
		}
		return "[ " + strings.Join(parts, ", ") + " ]"
	case KObject:
		if len(v.Keys) == 0 {
			return "{}"
		}
		parts := make([]string, len(v.Keys))
		for i, k := range v.Keys {
			parts[i] = escapeJSONString(k) + ": " + p.renderInline(v.Map[k])
		}
		return "{ " + strings.Join(parts, ", ") + " }"
	}
	return ""
}

// canInline decides if a value can be inlined at a given context.
// parentIsArray: true if value is inside an array; false if inside object or root.
// Rules derived from observation:
//
//	array:
//	  empty -> inline
//	  all elements numbers -> inline
//	  len==1 AND parent-is-object AND element is a primitive -> inline
//	  otherwise wrap
//	object:
//	  empty -> inline
//	  parent is array AND all values primitive -> inline
//	  otherwise wrap
func canInline(v *Value, parentIsArray bool) bool {
	switch v.K {
	case KArray:
		if len(v.Arr) == 0 {
			return true
		}
		allNum := true
		for _, c := range v.Arr {
			if c.K != KNumber {
				allNum = false
				break
			}
		}
		if allNum {
			return true
		}
		if !parentIsArray && len(v.Arr) == 1 {
			c := v.Arr[0]
			if isPrimitive(c) {
				return true
			}
		}
		return false
	case KObject:
		if len(v.Keys) == 0 {
			return true
		}
		if !parentIsArray {
			return false
		}
		for _, k := range v.Keys {
			c := v.Map[k]
			if !isPrimitive(c) {
				return false
			}
		}
		return true
	}
	return true
}

func isPrimitive(v *Value) bool {
	return v.K == KNull || v.K == KBool || v.K == KNumber || v.K == KString
}

// Max content width after indent for inline
const inlineContentLimit = 90 // approx

func (p *printer) write(s string) {
	p.buf.WriteString(s)
}

func (p *printer) printValue(v *Value, indent int, parentIsArray bool) {
	if v.K != KArray && v.K != KObject {
		// scalar
		p.write(p.renderInline(v))
		return
	}
	if p.noInline {
		p.printWrapped(v, indent)
		return
	}
	if canInline(v, parentIsArray) {
		inline := p.renderInline(v)
		// width check: runes length
		if utf8.RuneCountInString(inline) <= inlineContentLimit-indent {
			p.write(inline)
			return
		}
		// check if it's "all numbers" array – we observed they always inline regardless of width
		if v.K == KArray {
			allNum := true
			for _, c := range v.Arr {
				if c.K != KNumber {
					allNum = false
					break
				}
			}
			if allNum {
				p.write(inline)
				return
			}
		}
	}
	p.printWrapped(v, indent)
}

func (p *printer) printWrapped(v *Value, indent int) {
	switch v.K {
	case KArray:
		p.write("[\n")
		for i, c := range v.Arr {
			p.write(strings.Repeat(" ", indent+2))
			p.printValue(c, indent+2, true)
			if i < len(v.Arr)-1 {
				p.write(",")
			}
			p.write("\n")
		}
		p.write(strings.Repeat(" ", indent))
		p.write("]")
	case KObject:
		p.write("{\n")
		for i, k := range v.Keys {
			p.write(strings.Repeat(" ", indent+2))
			p.write(escapeJSONString(k))
			p.write(": ")
			c := v.Map[k]
			p.printValue(c, indent+2, false)
			if i < len(v.Keys)-1 {
				p.write(",")
			}
			p.write("\n")
		}
		p.write(strings.Repeat(" ", indent))
		p.write("}")
	}
}

func printResult(v *Value, noInline bool) {
	// Top-level string printed raw (no quotes)
	if v == nil {
		fmt.Println("undefined")
		return
	}
	if v.K == KString {
		fmt.Println(v.S)
		return
	}
	p := &printer{noInline: noInline}
	// At root, always wrap for array/object
	switch v.K {
	case KArray, KObject:
		p.printWrapped(v, 0)
	default:
		p.write(p.renderInline(v))
	}
	fmt.Println(p.buf.String())
}

// ---------- path evaluation ----------

type tok struct {
	kind string // "dot", "ident", "lbrack", "rbrack", "num", "str"
	text string
}

// Parse a simple path-like expression: ., .key, .key.sub, .key[0], .["key"], [0]
func evalPath(v *Value, expr string) (*Value, bool) {
	expr = strings.TrimSpace(expr)
	if expr == "" || expr == "." || expr == "this" {
		return v, true
	}
	cur := v
	i := 0
	if expr[i] == '.' {
		i++
	}
	for i < len(expr) {
		c := expr[i]
		if c == '.' {
			i++
			continue
		}
		if c == '[' {
			i++
			if i < len(expr) && expr[i] == '"' {
				// string key
				i++
				start := i
				for i < len(expr) && expr[i] != '"' {
					i++
				}
				key := expr[start:i]
				i++ // closing quote
				if i < len(expr) && expr[i] == ']' {
					i++
				}
				if cur == nil || cur.K != KObject {
					return nil, true
				}
				if val, ok := cur.Map[key]; ok {
					cur = val
				} else {
					return nil, true
				}
				continue
			}
			// numeric index
			start := i
			for i < len(expr) && expr[i] >= '0' && expr[i] <= '9' {
				i++
			}
			idx, err := strconv.Atoi(expr[start:i])
			if err != nil {
				return nil, false
			}
			if i < len(expr) && expr[i] == ']' {
				i++
			}
			if cur == nil || cur.K != KArray {
				return nil, true
			}
			if idx < 0 || idx >= len(cur.Arr) {
				return nil, true
			}
			cur = cur.Arr[idx]
			continue
		}
		// identifier
		start := i
		for i < len(expr) && (expr[i] == '_' || (expr[i] >= 'a' && expr[i] <= 'z') ||
			(expr[i] >= 'A' && expr[i] <= 'Z') || (expr[i] >= '0' && expr[i] <= '9')) {
			i++
		}
		if i == start {
			return nil, false
		}
		key := expr[start:i]
		if cur == nil {
			return nil, true
		}
		if cur.K == KObject {
			if val, ok := cur.Map[key]; ok {
				cur = val
				continue
			}
			return nil, true
		}
		if cur.K == KArray && key == "length" {
			return &Value{K: KNumber, N: strconv.Itoa(len(cur.Arr))}, true
		}
		if cur.K == KString && key == "length" {
			return &Value{K: KNumber, N: strconv.Itoa(utf8.RuneCountInString(cur.S))}, true
		}
		return nil, true
	}
	return cur, true
}

// ---------- main ----------

func stdinIsTerminal() bool {
	fi, err := os.Stdin.Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}

func stdoutIsTerminal() bool {
	fi, err := os.Stdout.Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}

func main() {
	f, special, kind, comp := parseArgs(os.Args[1:])
	if special {
		switch kind {
		case "help":
			fmt.Print(helpText)
			return
		case "version":
			fmt.Println(version)
			return
		case "themes":
			printThemes()
			return
		case "comp":
			switch comp {
			case "bash":
				fmt.Print(bashCompletion)
			case "zsh":
				fmt.Print(zshCompletion)
			case "fish":
				fmt.Print(fishCompletion)
			default:
				fmt.Println("unknown shell type")
			}
			return
		}
	}

	if f.gol {
		panicNoTTY()
		return
	}

	// Decide source: if first positional arg is a file path AND stdin is a terminal (no pipe), read from file
	// Determine if stdin has data
	stdinTerm := stdinIsTerminal()

	var inputData []byte
	var expressions []string

	if len(f.args) > 0 && !stdinTerm {
		// All args are expressions, read input from stdin
		expressions = f.args
	} else if len(f.args) > 0 && stdinTerm {
		// First arg should be a file; rest are expressions
		fname := f.args[0]
		data, err := os.ReadFile(fname)
		if err != nil {
			// Not a valid file. Treat all as expressions and try stdin
			panicNoTTY()
			return
		}
		inputData = data
		expressions = f.args[1:]
		// If no expressions, open TUI
		if len(expressions) == 0 {
			panicNoTTY()
			return
		}
	} else {
		// No args => TUI mode
		panicNoTTY()
		return
	}

	if inputData == nil {
		data, err := io.ReadAll(os.Stdin)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		inputData = data
	}

	if f.yaml || f.toml {
		// Minimal YAML/TOML: not supported, treat as JSON-esque
		// For now, fall back to JSON parser
	}

	var root *Value
	if f.raw {
		if f.slurp {
			// each line as string; combine into array
			lines := strings.Split(strings.TrimRight(string(inputData), "\n"), "\n")
			arr := &Value{K: KArray}
			for _, l := range lines {
				arr.Arr = append(arr.Arr, &Value{K: KString, S: l})
			}
			root = arr
		} else {
			root = &Value{K: KString, S: strings.TrimRight(string(inputData), "\n")}
		}
	} else {
		if f.slurp {
			// parse multiple values
			arr := &Value{K: KArray}
			p := &Parser{src: inputData, strict: f.strict}
			for {
				if err := p.skipWS(); err != nil {
					perr := err.(*parseErr)
					fmt.Fprint(os.Stderr, renderParseError(inputData, perr))
					os.Exit(1)
				}
				if p.pos >= len(p.src) {
					break
				}
				v, err := p.parseValue()
				if err != nil {
					perr := err.(*parseErr)
					fmt.Fprint(os.Stderr, renderParseError(inputData, perr))
					os.Exit(1)
				}
				arr.Arr = append(arr.Arr, v)
			}
			root = arr
		} else {
			if len(strings.TrimSpace(string(inputData))) == 0 {
				return
			}
			p := &Parser{src: inputData, strict: f.strict}
			v, err := p.parseValue()
			if err != nil {
				perr := err.(*parseErr)
				fmt.Fprint(os.Stderr, renderParseError(inputData, perr))
				os.Exit(1)
			}
			root = v
		}
	}

	// Apply expressions
	result := root
	for _, expr := range expressions {
		v, ok := evalPath(result, expr)
		if !ok {
			// Unsupported expression; just treat as undefined for now
			fmt.Println("undefined")
			return
		}
		result = v
	}

	if result == nil {
		fmt.Println("undefined")
		return
	}
	printResult(result, f.noInline)
	_ = stdoutIsTerminal
}
